var AppError = class extends Error {
  statusCode;
  constructor(statusCode, message) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
};

// src/app/modules/commentReactions/commentReactions.service.ts
var createCommentReaction = async (commentId, userId, payload) => {
  const existingReaction = await prisma.commentReactions.findFirst({
    where: {
      commentId,
      userId
    }
  });
  if (existingReaction) {
    throw new AppError(
      StatusCodes3.BAD_REQUEST,
      "You have already reacted to this comment"
    );
  }
  const createReaction = await prisma.commentReactions.create({
    data: {
      commentId,
      userId,
      type: payload.type
    }
  });
  return createReaction;
};
var removeCommentReaction = async (commentId, userId) => {
  const deletedReaction = await prisma.commentReactions.delete({
    where: {
      id: commentId,
      userId
    }
  });
  return deletedReaction;
};
